Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='properfixes', at=datetime(2026, 10, 27, 0, 0, 0), actor='owner', title='Only proper fixes: the real fix, measured, even in an outage', body='A fix removes the cause and says how it was measured. A workaround that hides the symptom, a fallback that swallows an error, or a guard for a state the types should forbid is not a fix; tighten the type or parse once at the edge instead.', rationale='A hidden symptom comes back as a harder bug.', supersedes=()))